//! FORM acceptCharset preserves authored metadata and existing UTF-8 transport.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://form-accept-charset.test/submit><input id=area name=q value=Seed><input id=charset type=hidden name=_charset_ value=author></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-accept-charset.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_accept_charset_canonical_exact_once_conversion_and_raw_units(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'acceptCharset');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get acceptCharset'||a.set.name!=='set acceptCharset'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'acceptCharset')||x.acceptCharset!=='')throw 'canonical';var calls=0;x.acceptCharset={toString:function(){calls++;return '  UTF-8\ud800  ';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.acceptCharset!=='  UTF-8\ud800  '||x.getAttributeNS(null,'accept-charset')!==x.acceptCharset)throw 'exact raw';x.acceptCharset=null;if(x.acceptCharset!=='null')throw 'ordinary null';x.acceptCharset=undefined;if(x.acceptCharset!=='undefined')throw 'ordinary undefined';"#);}
#[test]
fn form_accept_charset_inert_exact_attribute_name_namespace_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','accept-charset','foreign');x.setAttributeNS(null,'ACCEPT-CHARSET','upper');x.setAttributeNS(null,'acceptCharset','other');if(x.acceptCharset!=='')throw 'exact key';x.acceptCharset='A\ud800Z';var copy=x.cloneNode(false);copy.acceptCharset='copy';if(x.acceptCharset!=='A\ud800Z'||copy.acceptCharset!=='copy'||copy.getAttributeNodeNS(null,'accept-charset')===x.getAttributeNodeNS(null,'accept-charset')||x.getAttributeNS('urn:foreign','accept-charset')!=='foreign'||x.getAttributeNS(null,'acceptCharset')!=='other')throw 'independent copy';"#);}
#[test]
fn form_accept_charset_keeps_native_utf8_submission_and_hidden_charset_value_independent(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let hidden=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("charset")).unwrap();let loc=crate::navigation::address("https://form-accept-charset.test/source",&crate::navigation::Location::home()).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');document.getElementById('area').value='日😀';");for label in ["Shift_JIS"," windows-1252 ","UTF-8",""]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.acceptCharset='{label}';if(x.acceptCharset!=='{label}')throw 'unrestricted reflection';"));let result=f.submit_request(&d,owner,None,&loc,&loc).unwrap();let crate::http::Request::FormPost{body,..}=result.request else{panic!("POST")};assert_eq!(body,b"q=%E6%97%A5%F0%9F%98%80&_charset_=UTF-8");assert_eq!(f.controls[&hidden].value.text(),"author");}}

#[test]
fn form_accept_charset_named_control_precedence_preserves_saved_accessor_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'acceptCharset');n.setAttribute('name','acceptCharset');if(x.acceptCharset!==n)throw 'named control precedence';var calls=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,{toString:function(){calls++;return 'OFF';}});var records=watch.takeRecords();if(calls!==1||records.length!==1||records[0].attributeName!=='accept-charset'||x.acceptCharset!==n||a.get.call(x)!=='OFF'||x.getAttributeNS(null,'accept-charset')!=='OFF')throw 'saved authority';a.set.call(x,'off\\ud800');if(a.get.call(x)!=='off\\ud800'||x.getAttributeNS(null,'accept-charset')!=='off\\ud800')throw 'named raw setter';a.set.call(x,'OFF');n.setAttribute('name','q');if(x.acceptCharset!=='OFF')throw 'live named removal';");}
#[test]
fn form_accept_charset_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.acceptCharset='off';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_accept_charset_get(object).map(|_|())}else{bridge.form_accept_charset_set(object,&Value::String("growing-unknown-name-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.acceptCharset='ON';if(x.acceptCharset!=='ON'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_accept_charset_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.acceptCharset='on';var attribute=x.getAttributeNodeNS(null,'accept-charset'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['accept-charset']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('accept-charset','OFF');","x.setAttributeNS(null,'accept-charset','OFF');","attribute.value='OFF';","attribute.nodeValue='OFF';","attribute.textContent='OFF';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.acceptCharset='on';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.acceptCharset!=='OFF'||x.getAttributeNodeNS(null,'accept-charset')!==attribute||records.length!==1||records[0].oldValue!=='on'||records[0].attributeName!=='accept-charset'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('accept-charset');replacement.value='off\ud800';x.setAttributeNodeNS(replacement);if(x.acceptCharset!=='off\ud800'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='off\ud800')throw 'raw attribute replacement';"#);}

#[test]
fn form_accept_charset_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'acceptCharset'),calls=0;if(a.get.call(x)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-accept-charset.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-accept-charset.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.acceptCharset!=='ON')throw 'fresh recovery';");}

#[test]
fn form_accept_charset_brand_abrupt_conversion_and_prototype_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'acceptCharset'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.acceptCharset={toString:function(){calls++;x.acceptCharset='inner';return ' OUTER ';}};if(calls!==1||x.acceptCharset!==' OUTER ')throw 'once';var marker={};try{x.acceptCharset={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.acceptCharset!==' OUTER '||x.getAttribute('data-side')!=='kept')throw 'abrupt';Object.defineProperty(P,'acceptCharset',{get:function(){return 'author';},configurable:true});a.set.call(x,'native');if(x.acceptCharset!=='author'||a.get.call(x)!=='native')throw 'saved authority';delete P.acceptCharset;if(x.acceptCharset!==undefined)throw 'deleted canonical';Object.defineProperty(P,'acceptCharset',a);var C=HTMLFormElement;delete window.HTMLFormElement;if(!(x instanceof C)||a.get.call(x)!=='native')throw 'saved constructor';"#);}
